    private static readonly ConcurrentDictionary<string, Geometry> Geometries = new();

    private static Geometry Glyph(string key)
    {
        if (!Paths.ContainsKey(key)) key = "Shape";
        return Geometries.GetOrAdd(key, name =>
        {
            var geometry = Geometry.Parse(Paths[name]);
            geometry.Freeze();
            return geometry;
        });
    }

    public static FrameworkElement Content(string key, string label, double size = 16)
    {
        var row = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(2, 1, 2, 1)
        };
        var path = new IconPath { Data = Glyph(key), IsHitTestVisible = false };
        path.SetBinding(Shape.FillProperty, new Binding(nameof(Control.Foreground))
        {
            RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, typeof(Control), 1)
        });
        var viewport = new Canvas { Width = 24, Height = 24, IsHitTestVisible = false };
        viewport.Children.Add(path);
        var icon = new Viewbox
        {
            Width = size,
            Height = size,
            Child = viewport
        };
        var box = new Grid
        {
            Width = size + 4,
            Height = size + 4,
            Margin = new Thickness(0, 0, string.IsNullOrEmpty(label) ? 0 : 5, 0),
            SnapsToDevicePixels = true
        };
        icon.HorizontalAlignment = HorizontalAlignment.Center;
        icon.VerticalAlignment = VerticalAlignment.Center;
        box.Children.Add(icon);
        row.Children.Add(box);
        if (!string.IsNullOrEmpty(label))
            row.Children.Add(new TextBlock { Text = label, VerticalAlignment = VerticalAlignment.Center });
        return row;
    }
}
